import { useState } from 'react';
import { MapPin, ShoppingCart } from 'lucide-react';
import { OrderModal } from '../orders/OrderModal'; 
import { useCart } from '../../context/CartContext'; // Import Cart Context

const getStatusStyles = (status) => {
  switch (status) {
    case 'Fresh': return 'bg-green-500 text-white';
    case 'High Demand': return 'bg-farmOrange text-white';
    case 'Good Quality': return 'bg-yellow-400 text-yellow-900';
    case 'Pending': return 'bg-orange-100 text-orange-800';
    default: return 'bg-gray-200 text-gray-800';
  }
};

export const ProduceCard = ({ item }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { addToCart } = useCart(); // Destructure the cart function

  return (
    <>
      <article className="bg-white rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow overflow-hidden flex flex-col">
        
        {/* Image & Badges */}
        <div className="h-48 w-full bg-gray-100 relative">
          <img 
            src={`https://source.unsplash.com/400x300/?${item.cropType.toLowerCase()},farm`} 
            alt={item.cropType}
            className="w-full h-full object-cover"
            onError={(e) => { e.target.src = 'https://via.placeholder.com/400x300?text=FarmLink' }}
          />
          <span className={`absolute top-3 right-3 px-3 py-1 text-xs font-bold rounded-full shadow-sm ${getStatusStyles(item.status)}`}>
            {item.status}
          </span>
        </div>

        {/* Content Body */}
        <div className="p-4 flex flex-col flex-1">
          <h3 className="text-lg font-bold text-gray-900">{item.cropType}</h3>
          <p className="text-sm text-gray-500 mb-3">{item.weightKg.toLocaleString()} kg available</p>
          
          <div className="flex items-center text-xs text-gray-500 mb-4">
            <MapPin size={14} className="mr-1 text-farmGreen" />
            <span className="truncate">{item.location}</span>
          </div>

          <div className="mt-auto flex items-center justify-between border-t border-gray-100 pt-4">
            <div className="flex flex-col">
              <span className="text-lg font-bold text-gray-900">
                GHS {item.pricePerKg.toFixed(2)}
              </span>
              <span className="text-xs text-gray-500">per kg</span>
            </div>
            
            {/* Action Buttons: Add to Cart AND Order Now */}
            <div className="flex items-center gap-2">
              <button 
                onClick={() => addToCart(item)}
                className="p-2 bg-green-50 text-farmGreen hover:bg-green-100 rounded-lg transition-colors border border-green-200"
                title="Add to Cart"
              >
                <ShoppingCart size={18} />
              </button>
              <button 
                onClick={() => setIsModalOpen(true)}
                className="px-4 py-2 bg-farmGreen hover:bg-farmGreen-dark text-white text-sm font-semibold rounded-lg transition-colors"
              >
                Order Now
              </button>
            </div>
          </div>
        </div>
      </article>

      {/* Standard Order Modal Component */}
      {isModalOpen && (
        <OrderModal 
          item={item} 
          onClose={() => setIsModalOpen(false)} 
        />
      )}
    </>
  );
};
